fn ready_history(result: Result<Vec<HistoryEntry>, NodeError>) -> Option<Vec<HistoryEntry>> {
    match result {
        Ok(history) => Some(history),
        Err(NodeError::Log(LogError::StaleCursor)) => None,
        Err(error) => panic!("history observation failed: {error}"),
    }
}

