    pub fn dm_history(
        &self,
        peer: &PublicIdentity,
        limit: usize,
    ) -> Result<Vec<HistoryEntry>, super::NodeError> {
        let conv = dm_conversation_id(&self.identity.public(), peer);
        self.history(conv, limit)
    }

    /// Account-level conversation history with `peer_account_id`, merging our sent
